'use strict';
(()=>{
const cache=new Map();let active=null;
function parse(bytes){const b=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);if(b.length>=26&&String.fromCharCode(...b.slice(0,4))==='fLaC'&&(b[4]&127)===0){const sampleRate=(b[18]<<12)|(b[19]<<4)|(b[20]>>4),bitDepth=(((b[20]&1)<<4)|(b[21]>>4))+1;if(sampleRate>0&&bitDepth>=4&&bitDepth<=32)return {codec:'FLAC',lossless:true,bitDepth,sampleRate,channels:((b[20]>>1)&7)+1,verified:true}}
if(b.length>=12&&String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WAVE'){const v=new DataView(b.buffer,b.byteOffset,b.byteLength);for(let offset=12;offset+8<=b.length;){const size=v.getUint32(offset+4,true),next=offset+8+size+(size%2);if(String.fromCharCode(...b.slice(offset,offset+4))==='fmt '&&size>=16&&offset+24<=b.length){let code=v.getUint16(offset+8,true);if(code===65534&&size>=40&&offset+48<=b.length)code=v.getUint16(offset+32,true);const sampleRate=v.getUint32(offset+12,true),bitDepth=v.getUint16(offset+22,true);if([1,3].includes(code)&&sampleRate>0&&[8,16,24,32,64].includes(bitDepth))return {codec:'WAV PCM',lossless:true,bitDepth,sampleRate,verified:true};return null}if(next<=offset||next>b.length)break;offset=next}}return null}
function label(track){const q=track.quality;if(q?.verified)return `LOSSLESS · ${q.bitDepth}-BIT · ${q.sampleRate/1000} kHz`;if(track.provider==='HiFi'&&track.lossyFallback)return 'LOSSY · '+track.sourceCodec; if(track.lossyFallback)return 'LOSSY FALLBACK · '+(track.sourceCodec||'quality unverified');return track.sourceCodec?`${track.sourceCodec} · bits unverified`:'Quality unverified'}
async function probe(track,fetcher=fetch){active?.abort();if(track.quality?.verified)return track.quality;if(cache.has(track.url))return cache.get(track.url);if(!/^https:\/\//.test(track.url))return null;const controller=new AbortController();active=controller;const timeout=setTimeout(()=>controller.abort(),5000);let reader;try{const response=await fetcher(track.url,{headers:{Range:'bytes=0-4095'},signal:controller.signal,credentials:typeof location!=='undefined'&&new URL(track.url).origin===location.origin?'same-origin':'omit',referrerPolicy:'no-referrer'});if(!response.ok||!response.body)return null;reader=response.body.getReader();const buffer=new Uint8Array(4096);let total=0,result=null;while(total<buffer.length){const chunk=await reader.read();if(chunk.done)break;const part=chunk.value.subarray(0,buffer.length-total);buffer.set(part,total);total+=part.length;result=parse(buffer.subarray(0,total));if(result)break}if(result){cache.set(track.url,result);if(cache.size>50)cache.delete(cache.keys().next().value)}return result}catch{return null}finally{clearTimeout(timeout);if(reader)try{await reader.cancel()}catch{}if(active===controller)active=null}}
window.MonoAudioQuality={parse,label,probe};
})();
